-- 匯入新北市公立國小官方名錄(教育部統計處114學年度國民小學名錄,新北市部分,
-- 86 校;僅收錄已核對之地址/電話/網站等基礎資料,校長與四處主任、學生人數
-- 均待查證,故不隨本次匯入,待各校逐一查核後再行補登,見 school_staff。
-- 以 school_code(教育部名錄校代碼)為鍵,ON DUPLICATE KEY UPDATE 可重複套用、
-- 供後續名錄更新時以同一 migration 機制重新匯入最新資料。

ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  category = VALUES(category),
  district = VALUES(district),
  address = VALUES(address),
  phone = VALUES(phone),
  website = VALUES(website),
  notes = VALUES(notes),
  updated_at = NOW();
